import {knowledge} from './coach-knowledge.mjs';
import {answer} from './coach-search.mjs';
const style=document.createElement('link');style.rel='stylesheet';style.href=new URL('./coach.css',import.meta.url);document.head.append(style);
const host=document.createElement('div');host.id='ml-coach';document.body.append(host);
let lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi';
const t=(vi,en)=>lang==='vi'?vi:en;
const launch=document.createElement('button');launch.className='coach-launch';launch.textContent='? Coach';launch.setAttribute('aria-expanded','false');launch.setAttribute('aria-controls','coach-panel');
const panel=document.createElement('section');panel.id='coach-panel';panel.hidden=true;panel.setAttribute('aria-label','Money Lab Coach');
const header=document.createElement('header');const title=document.createElement('strong');title.textContent='Money Lab Coach';const language=document.createElement('button');const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Close Coach');header.append(title,language,close);
const note=document.createElement('p');note.className='coach-note';const log=document.createElement('div');log.className='coach-log';log.setAttribute('role','log');log.setAttribute('aria-live','polite');
const topics=document.createElement('div');topics.className='coach-topics';const form=document.createElement('form');const input=document.createElement('input');input.maxLength=600;input.autocomplete='off';const send=document.createElement('button');send.type='submit';form.append(input,send);const clear=document.createElement('button');clear.className='coach-clear';
panel.append(header,note,log,topics,form,clear);host.append(launch,panel);
function labels(){language.textContent=lang==='vi'?'EN':'VI';note.textContent=t('Hướng dẫn từ tài liệu · Không dùng token AI · Không đọc chặng hoặc kiểm tra ví trực tiếp. Đừng gửi thông tin bí mật.','Document-based help · No AI tokens · No live session or wallet access. Never share secrets.');input.placeholder=t('Hỏi về Money Lab…','Ask about Money Lab…');input.setAttribute('aria-label',t('Câu hỏi cho Coach','Question for Coach'));send.textContent=t('Hỏi','Ask');clear.textContent=t('Xóa hội thoại','Clear chat');topics.replaceChildren();for(const k of knowledge){const b=document.createElement('button');b.textContent=k[lang+'q'];b.onclick=()=>ask(k[lang+'q'],k.id);topics.append(b);}}
function message(text,kind){const div=document.createElement('div');div.className='coach-message '+kind;div.textContent=text;log.append(div);while(log.children.length>24)log.firstChild.remove();return div;}
function ask(question,id){const q=question.trim();if(!q)return;const secret=/\b(seed phrase|private key|khoa rieng|mat khau|mnemonic|password)\b/i.test(q)||q.split(/\s+/).length>=12&&q.split(/\s+/).every(w=>/^[a-z]+$/i.test(w))||/0x[a-f0-9]{64}\b/i.test(q);message(secret?t('[Đã ẩn nội dung để bảo vệ thông tin]','[Content hidden to protect private information]'):q,'user');input.value='';const item=secret?knowledge.find(x=>x.id==='privacy'):answer(q,lang,id);const div=message(item?item[lang]:t('Em chưa tìm được câu trả lời chắc chắn trong tài liệu Money Lab. Anh/chị hãy chọn một chủ đề bên dưới hoặc hỏi rõ hơn. Coach không tư vấn đầu tư ngoài game và không kiểm tra số dư/giao dịch trực tiếp.','I could not find a confident answer in Money Lab documentation. Choose a topic below or make the question more specific. Coach does not provide outside-game investment advice or live balance/transaction checks.'),'assistant');if(item){const a=document.createElement('a');a.href=item.source;a.textContent=t('Mở phần liên quan ↗','Open related page ↗');div.append(document.createElement('br'),a);}log.scrollTop=log.scrollHeight;}
function opened(value){panel.hidden=!value;launch.setAttribute('aria-expanded',String(value));if(value)input.focus();else launch.focus();}
launch.onclick=()=>opened(panel.hidden);close.onclick=()=>opened(false);language.onclick=()=>{lang=lang==='vi'?'en':'vi';labels();};form.onsubmit=e=>{e.preventDefault();ask(input.value);};clear.onclick=()=>{log.replaceChildren();input.value='';};host.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden)opened(false);});new MutationObserver(()=>{lang=document.documentElement.lang.startsWith('en')?'en':'vi';labels();}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});labels();
